<?php
namespace Delnavazan\Platform\Core\Application; use Delnavazan\Platform\Core\Infrastructure\Repository\TeacherRepository;
final class TeacherService { public function create(array $d):int{if(!current_user_can('dzn_manage_teachers'))throw new \RuntimeException('Unauthorized');$d['status']=Normalizer::one($d['status']??'active',['active','inactive'],'teacher state');foreach(['persian_name','english_name','city']as$f)$d[$f]=Normalizer::text($d[$f]??null);$d['display_name']=Normalizer::text($d['display_name']??'',191,true);$d['email']=Normalizer::email($d['email']??null);foreach(['phone','whatsapp_phone']as$f)$d[$f]=Normalizer::phone($d[$f]??null);$d['country_code']=Normalizer::country($d['country_code']??'IR');$d['timezone']=Normalizer::timezone($d['timezone']??'Asia/Tehran');$d['timezone_source']=Normalizer::timezoneSource($d['timezone_source']??'admin_selected');$d['locale']=Normalizer::locale($d['locale']??'fa_IR');$d['calendar_preference']=Normalizer::one($d['calendar_preference']??'persian',['auto','gregorian','persian'],'calendar');$d['wordpress_user_id']=Normalizer::id($d['wordpress_user_id']??null,false);return Creator::create(new TeacherRepository,$d,'DZN-TCH-');} }
